1	// `cheerio/slim` is the parse-only entry: it drops cheerio's URL-loading stack
2	// (undici, encoding-sniffer, whatwg-mimetype) which doesn't run on Workers and
3	// added ~1 MiB to the bundle. We only ever call `load()` on an already-fetched
4	// HTML string, so the slim build is a drop-in.
5	import * as cheerio from "cheerio/slim";
6	
7	export type FetchedMetadata = {
8	  title: string | null;
9	  description: string | null;
10	  faviconUrl: string | null;
11	  ogImageUrl: string | null;
12	  contentLanguage: string | null;
13	  extractedText: string | null;
14	  estimatedReadMinutes: number | null;
15	};
16	
17	export type FetchMetadataResult =
18	  | { status: "success"; metadata: FetchedMetadata }
19	  | { status: "error"; error: string };
20	
21	const FETCH_TIMEOUT_MS = 8000;
22	const EXTRACTED_TEXT_CAP = 4000;
23	const WORDS_PER_MINUTE = 200;
24	
25	function absoluteUrl(base: string, maybeRelative: string | undefined): string | null {
26	  if (!maybeRelative) return null;
27	  try {
28	    return new URL(maybeRelative, base).toString();
29	  } catch {
30	    return null;
31	  }
32	}
33	
34	function detectLanguage(html: cheerio.CheerioAPI, text: string): string | null {
35	  const htmlLang = html("html").attr("lang");
36	  if (htmlLang) return htmlLang.split("-")[0].toLowerCase();
37	  // Cheap heuristic fallback: a meaningful share of CJK codepoints implies Japanese.
38	  const sample = text.slice(0, 400);
39	  const cjkMatches = sample.match(/[぀-ヿ㐀-䶿一-鿿]/g);
40	  if (cjkMatches && cjkMatches.length / Math.max(sample.length, 1) > 0.15) return "ja";
41	  return "en";
42	}
43	
44	export async function fetchUrlMetadata(url: string): Promise<FetchMetadataResult> {
45	  try {
46	    const response = await fetch(url, {
47	      redirect: "follow",
48	      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
49	      headers: {
50	        "User-Agent": "HazyBot/1.0 (+https://hazy.app; link preview fetcher)",
51	        Accept: "text/html,application/xhtml+xml",
52	      },
53	    });
54	
55	    if (!response.ok) {
56	      return { status: "error", error: `Fetch failed with status ${response.status}` };
57	    }
58	
59	    const contentType = response.headers.get("content-type") ?? "";
60	    if (!contentType.includes("text/html") && !contentType.includes("xhtml")) {
61	      return { status: "error", error: `Unsupported content type: ${contentType || "unknown"}` };
62	    }
63	
64	    const html = await response.text();
65	    const $ = cheerio.load(html);
66	    const finalUrl = response.url || url;
67	
68	    const ogTitle = $('meta[property="og:title"]').attr("content");
69	    const titleTag = $("title").first().text();
70	    const title = (ogTitle || titleTag || "").trim() || null;
71	
72	    const ogDescription = $('meta[property="og:description"]').attr("content");
73	    const metaDescription = $('meta[name="description"]').attr("content");
74	    const description = (ogDescription || metaDescription || "").trim() || null;
75	
76	    const ogImage = $('meta[property="og:image"]').attr("content");
77	    const ogImageUrl = absoluteUrl(finalUrl, ogImage);
78	
79	    const iconHref =
80	      $('link[rel="icon"]').attr("href") ??
81	      $('link[rel="shortcut icon"]').attr("href") ??
82	      $('link[rel="apple-touch-icon"]').attr("href");
83	    const faviconUrl = absoluteUrl(finalUrl, iconHref) ?? absoluteUrl(finalUrl, "/favicon.ico");
84	
85	    $("script, style, noscript, nav, footer").remove();
86	    const bodyText = $("body").text().replace(/\s+/g, " ").trim();
87	    const extractedText = bodyText ? bodyText.slice(0, EXTRACTED_TEXT_CAP) : null;
88	
89	    const wordCount = bodyText ? bodyText.split(/\s+/).length : 0;
90	    const estimatedReadMinutes = wordCount
91	      ? Math.max(1, Math.round(wordCount / WORDS_PER_MINUTE))
92	      : null;
93	
94	    const contentLanguage = detectLanguage($, bodyText);
95	
96	    return {
97	      status: "success",
98	      metadata: {
99	        title,
100	        description,
101	        faviconUrl,
102	        ogImageUrl,
103	        contentLanguage,
104	        extractedText,
105	        estimatedReadMinutes,
106	      },
107	    };
108	  } catch (error) {
109	    const message =
110	      error instanceof Error
111	        ? error.name === "TimeoutError" || error.name === "AbortError"
112	          ? "Timed out fetching the page."
113	          : error.message
114	        : "Unknown fetch error";
115	    return { status: "error", error: message };
116	  }
117	}
