16	async function loadOwnedItem(userId: string, id: string) {
17	  const db = getDb();
18	  const row = await db.query.savedUrls.findFirst({
19	    where: and(eq(savedUrls.id, id), eq(savedUrls.userId, userId)),
20	    with: { readLaterState: true },
