26	/** Lowercase, trim, drop blanks/overlong entries, de-dupe, cap the list. */
27	function normalizeTags(tags: string[]): string[] {
28	  const seen = new Set<string>();
29	  for (const raw of tags) {
30	    const tag = raw.trim().toLowerCase();
31	    if (tag && tag.length <= 50) seen.add(tag);
32	  }
33	  return [...seen].slice(0, 30);
34	}
