22	/** x.com / twitter.com URLs block scraping, so metadata + images never come
23	 *  through — fxtwitter.com mirrors the same path and actually serves them. */
24	function fxtwitterUrl(raw: string): string | null {
25	  let parsed: URL;
26	  try {
27	    parsed = new URL(raw);
28	  } catch {
29	    return null;
30	  }
31	  const host = parsed.hostname.replace(/^www\./, "");
32	  if (host !== "x.com" && host !== "twitter.com") return null;
33	  parsed.hostname = "fxtwitter.com";
34	  return parsed.toString();
35	}
