37	export function SaveUrlDialog({ triggerLabel }: { triggerLabel: string }) {
38	  const t = useTranslations("save");
39	  const [open, setOpen] = useState(false);
40	  const [url, setUrl] = useState("");
41	  const mutation = useSaveUrlMutation();
42	  const router = useRouter();
43	
44	  const fxUrl = useMemo(() => fxtwitterUrl(url.trim()), [url]);
45	
46	  async function handleSubmit(e: React.FormEvent) {
