51	        setOpen(false);
52	        setUrl("");
53	        toast.success(saved.title ?? saved.url);
54	        router.push(`/item/${saved.id}`);
55	      },
56	      onError: (error) => {
57	        toast.error(error instanceof Error ? error.message : "Could not save that link.");
58	      },
59	    });
60	  }
61	
62	  return (
63	    <Dialog open={open} onOpenChange={setOpen}>
64	      <DialogTrigger asChild>
65	        <Button size="sm" className="gap-1.5">
66	          <Plus className="size-4" />
67	          <span className="hidden sm:inline">{triggerLabel}</span>
68	        </Button>
69	      </DialogTrigger>
70	      <DialogContent>
71	        <form onSubmit={handleSubmit}>
72	          <DialogHeader>
73	            <DialogTitle>{t("title")}</DialogTitle>
74	            <DialogDescription>
75	              {mutation.isPending ? t("fetching") : t("urlPlaceholder")}
76	            </DialogDescription>
77	          </DialogHeader>
78	          <div className="my-4 flex flex-col gap-2">
79	            <Label htmlFor="save-url-input">{t("urlLabel")}</Label>
80	            <Input
81	              id="save-url-input"
82	              autoFocus
83	              placeholder={t("urlPlaceholder")}
84	              value={url}
85	              onChange={(e) => setUrl(e.target.value)}
86	              disabled={mutation.isPending}
87	            />
88	            {fxUrl && (
89	              <a
90	                href={fxUrl}
91	                target="_blank"
92	                rel="noreferrer"
93	                className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground hover:underline"
94	              >
95	                <Download className="size-3" />
96	                {t("fxtwitterHint")}
97	              </a>
98	            )}
