57	    const token = await config.getToken();
58	    const res = await fetch(url, {
59	      method: init.method ?? "GET",
60	      headers: {
61	        ...(init.body !== undefined ? { "Content-Type": "application/json" } : {}),
62	        ...(token ? { Authorization: `Bearer ${token}` } : {}),
63	      },
64	      body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
65	      signal: init.signal,
66	    });
67	
68	    const json = (await res.json().catch(() => null)) as Envelope<T> | null;
69	    if (json && "error" in json) {
70	      throw new ApiClientError(json.error.code, json.error.message, res.status, json.error.details);
71	    }
72	    if (!res.ok || !json || !("data" in json)) {
