4	/** Success envelope: `{ data: T }`. */
5	export function ok<T>(data: T, init?: { status?: number }): Response {
6	  return Response.json({ data }, { status: init?.status ?? 200 });
7	}
8	
9	/**
10	 * Failure envelope: `{ error: { code, message, details? } }`. Used as the body
11	 * of Hono's `onError` — every thrown `ApiError` / `ZodError` maps here, anything
12	 * else becomes a logged 500.
13	 */
14	export function fail(error: unknown): Response {
15	  if (error instanceof ApiError) {
16	    return Response.json(
17	      { error: { code: error.code, message: error.message, details: error.details } },
18	      { status: error.status }
19	    );
20	  }
21	  if (error instanceof ZodError) {
22	    return Response.json(
23	      {
24	        error: {
25	          code: "validation_error",
26	          message: "Request validation failed.",
27	          details: error.flatten(),
28	        },
29	      },
30	      { status: 400 }
31	    );
32	  }
33	  console.error("Unhandled API error:", error);
34	  return Response.json(
35	    { error: { code: "internal_error", message: "Something went wrong." } },
36	    { status: 500 }
37	  );
38	}
