14	  } catch {
15	    throw new ValidationError("That doesn't look like a valid URL.");
16	  }
17	
18	  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
19	    throw new ValidationError("Only http:// and https:// links can be saved.");
20	  }
21	
22	  const normalized = new URL(parsed.toString());
23	  normalized.hostname = normalized.hostname.toLowerCase();
24	  normalized.hash = "";
25	
26	  const paramsToDelete: string[] = [];
27	  normalized.searchParams.forEach((_value, key) => {
28	    const lowerKey = key.toLowerCase();
29	    if (
30	      TRACKING_PARAMS.has(lowerKey) ||
31	      TRACKING_PARAM_PREFIXES.some((prefix) => lowerKey.startsWith(prefix))
32	    ) {
33	      paramsToDelete.push(key);
34	    }
35	  });
36	  paramsToDelete.forEach((key) => {
37	    normalized.searchParams.delete(key);
38	  });
39	
40	  // Trailing slash on a bare path is cosmetic — treat `example.com` and
41	  // `example.com/` as the same save.
42	  let normalizedString = normalized.toString();
43	  if (normalized.pathname === "/" && normalizedString.endsWith("/")) {
44	    normalizedString = normalizedString.slice(0, -1);
45	  }
46	
47	  return {
48	    url: parsed.toString(),
49	    normalizedUrl: normalizedString,
50	    domain: normalized.hostname.replace(/^www\./, ""),
51	  };
