import { chromium } from "playwright";
import { clerkSetup, clerk } from "@clerk/testing/playwright";

process.env.CLERK_SECRET_KEY = "REDACTED";
process.env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY =
  "REDACTED";

const email = "n.knight.pc0627@gmail.com";

const browser = await chromium.launch();
const context = await browser.newContext({ acceptDownloads: true });
const page = await context.newPage();

page.on("console", (msg) => console.log("[console]", msg.type(), msg.text()));
page.on("pageerror", (err) => console.log("[pageerror]", err.message));

try {
  await clerkSetup({ frontendApiUrl: undefined });
} catch (e) {
  console.log("clerkSetup warn:", e.message);
}

await page.goto("http://localhost:3100/sign-in");
await clerk.signIn({ page, emailAddress: email });
await page.goto("http://localhost:3100/en/library");
await page.waitForURL("**/en/library**", { timeout: 15000 });
console.log("Signed in, at library page:", page.url());

// Open save dialog and save an x.com URL.
await page.getByRole("button", { name: /save/i }).first().click();
const input = page.getByLabel("URL");
await input.fill("https://x.com/jack/status/20");
await page.getByRole("button", { name: /^save$/i }).click();

await page.waitForURL("**/item/**", { timeout: 20000 });
console.log("Item page:", page.url());
await page.waitForTimeout(1500);

// Click the download-image button.
const downloadBtn = page.getByRole("button", { name: /download image/i });
await downloadBtn.waitFor({ state: "visible", timeout: 10000 });

const [download] = await Promise.all([
  page.waitForEvent("download", { timeout: 20000 }),
  downloadBtn.click(),
]);

const suggested = download.suggestedFilename();
const failure = await download.failure();
console.log("RESULT download filename:", suggested);
console.log("RESULT download failure:", failure);
const path = await download.path();
console.log("RESULT download path:", path);

if (path) {
  const fs = await import("node:fs");
  const stat = fs.statSync(path);
  console.log("RESULT downloaded file size bytes:", stat.size);
}

await browser.close();

